484	          c.markAsUntouched();
485	        }
486	      }
487	      for (const t of gracesToSave) {
488	        const saved = await this.api.setGrace(t.grade, t.value === '' ? null : t.value, from(t.fromControl));
489	        this.gradeGraces.set(saved.gradeGraces);
490	        for (const c of [t.control, t.fromControl]) {
491	          c.markAsPristine();
492	          c.markAsUntouched();
493	        }
494	      }
495	      if (saveLatePct && latePctValue !== '') {
496	        const saved = await this.api.setLatePct(latePctValue, from(latePctFrom));
497	        this.latePct.set(saved.latePct);
498	        for (const c of [latePct, latePctFrom]) {
499	          c.markAsPristine();
500	          c.markAsUntouched();
501	        }
502	      }
503	      if (savePolicyDate) {
504	        const saved = await this.api.setPolicyDate(policyDateValue === '' ? null : policyDateValue);
505	        this.policyDate.set(saved.policyDate);
506	        policyDate.markAsPristine();
507	        policyDate.markAsUntouched();
508	      }
509	      if (saveNumbering) {
510	        const saved = await this.api.setPeriodNumberingFrom(numberingValue === '' ? null : numberingValue);
511	        this.periodNumberingFrom.set(saved.periodNumberingFrom);
512	        periodNumberingFrom.markAsPristine();
513	        periodNumberingFrom.markAsUntouched();
514	      }
515	      if (saveGrace) {
516	        const saved = await this.api.setGraceDays(graceValue === '' ? null : graceValue);
517	        this.graceDays.set(saved.graceDays);
518	        graceDays.markAsPristine();
519	        graceDays.markAsUntouched();
520	      }
521	      if (saveEntryDate) {
522	        const saved = await this.api.setEntryDate(entryDateValue === '' ? null : entryDateValue);
523	        this.entryDate.set(saved.entryDate);
524	        entryDate.markAsPristine();
525	        entryDate.markAsUntouched();
526	      }
527	      for (const p of permsToSave) {
528	        const saved = await this.api.setPermission(p.action, p.value === '' ? null : p.value);
529	        this.permissions.set(saved.permissions);
530	        p.control.markAsPristine();
531	        p.control.markAsUntouched();
532	      }
533	      // a blank field entered and left, and not saved, is not taken as changed by the next save
534	      this.settingsForm.markAsUntouched();
535	    } catch {
536	      this.settingsError.set('The settings could not be saved.');
537	    } finally {
538	      this.submitting = false;
539	    }
540	  }
541	
542	  /** The terms in force for a grade: its own, or else the sheet's. */
543	  protected termsOf(g: Grade): number | null {
544	    return this.gradeTerms()[g] ?? this.terms();
545	  }
546	
547	  protected async saveRole(): Promise<void> {
548	    if (this.submitting) return;
549	    this.roleError.set('');
550	    const user = this.roleForm.getRawValue().user.trim();
551	    const role = this.roleForm.getRawValue().role.trim();
552	    if (user === '') {
553	      this.roleError.set('Enter a user name.');
554	      return;
555	    }
556	    if (!(ROLES as string[]).includes(role)) {
557	      this.roleError.set('Choose a role of clerk, steward or viewer.');
558	      return;
559	    }
560	    this.submitting = true;
561	    try {
562	      const saved = await this.api.setRole(user, role as RoleName);
563	      this.roles.update((rs) =>
564	        [...rs.filter((r) => r.user !== saved.user), saved].sort((a, b) => a.user.localeCompare(b.user)),
565	      );
566	      this.roleForm.reset({ user: '', role: '' }, { emitEvent: false });
567	    } catch {
568	      this.roleError.set('The role could not be set.');
569	    } finally {
570	      this.submitting = false;
571	    }
572	  }
573	
574	  private async reload(sheetId: string): Promise<void> {
575	    const read = ++this.reads;
576	    try {
577	      const [settings, roles] = await Promise.all([this.api.get(sheetId), this.api.roles(sheetId)]);
578	      if (read === this.reads) {
579	        this.clerkLimit.set(settings.clerkLimit);
580	        this.cap.set(settings.cap);
581	        this.proofThreshold.set(settings.proofThreshold);
582	        this.noteThreshold.set(settings.noteThreshold);
583	        this.floor.set(settings.floor);
584	        this.terms.set(settings.terms);
585	        this.gradeTerms.set(settings.gradeTerms);
586	        this.gradeGraces.set(settings.gradeGraces);
587	        this.gradeProofThresholds.set(settings.gradeProofThresholds);
588	        this.latePct.set(settings.latePct);
589	        this.policyDate.set(settings.policyDate);
590	        this.periodNumberingFrom.set(settings.periodNumberingFrom);
591	        this.graceDays.set(settings.graceDays);
592	        this.entryDate.set(settings.entryDate);
593	        this.permissions.set(settings.permissions);
594	        this.roles.set(roles);
595	      }
